# ---------------------------------------------------------------------------
# Anwenden: aus den deutschen Inhalten die Inhalte in der gewählten Sprache
# machen. Alles, wofür es oben keinen Eintrag gibt, bleibt deutsch.
# ---------------------------------------------------------------------------
def _lektion(lektion, t):
    erklaerung = []
    for teil in lektion.get("erklaerung", []):
        if isinstance(teil, dict) and "tabelle" in teil:
            erklaerung.append({"tabelle": [[t(zelle) for zelle in reihe] for reihe in teil["tabelle"]]})
        else:
            erklaerung.append(t(teil))
    uebungen = [dict(u,
                     frage=t(u.get("frage", "")),
                     tipp=t(u.get("tipp", "")),
                     optionen=[t(o) for o in u.get("optionen", [])],
                     richtig=t(u.get("richtig", "")))
                for u in lektion.get("uebungen", [])]
    return dict(lektion, erklaerung=erklaerung, uebungen=uebungen)


def _geschichte(g, t):
    # "titel" und "text" bleiben bosnisch, das ist ja der Lernstoff.
    fragen = [dict(f,
                   frage=t(f.get("frage", "")),
                   optionen=[t(o) for o in f.get("optionen", [])],
                   richtig=t(f.get("richtig", "")))
              for f in g.get("fragen", [])]
    return dict(g,
                stufe=t(g.get("stufe", "")),
                uebersetzung=t(g.get("uebersetzung", "")),
                vokabeln={k: t(v) for k, v in (g.get("vokabeln") or {}).items()},
                fragen=fragen)


def anwenden(daten, code):
    """Liefert die Lerninhalte in der Sprache 'code'. Fehlt eine Übersetzung,
    bleibt der deutsche Text stehen."""
    if code == GRUNDSPRACHE or code not in INHALT:
        return daten
    tabelle = INHALT[code].get("texte", {})
    woerter = INHALT[code].get("woerter", {})

    def t(text):
        return tabelle.get(text, text) if isinstance(text, str) else text

    neu = dict(daten)
    neu["sektionen"] = [dict(s, label=t(s.get("label", "")), beschreibung=t(s.get("beschreibung", "")))
                        for s in daten.get("sektionen", [])]
    neu["kategorien"] = [dict(k,
                              label=t(k.get("label", "")),
                              tipp=t(k.get("tipp", "")),
                              words=[dict(w, de=woerter.get(w.get("bs", ""), t(w.get("de", ""))))
                                     for w in k.get("words", [])])
                         for k in daten.get("kategorien", [])]
    neu["saetze"] = [dict(s, de=t(s.get("de", ""))) for s in daten.get("saetze", [])]
    neu["grammatik"] = {kid: _lektion(l, t) for kid, l in daten.get("grammatik", {}).items()}
    neu["geschichten"] = [_geschichte(g, t) for g in daten.get("geschichten", [])]
    neu["woerterbuch"] = {k: t(v) for k, v in daten.get("woerterbuch", {}).items()}
    return neu


# ---------------------------------------------------------------------------
# Was fehlt noch? Für die Meldung beim Start und für die Arbeitsliste.
# ---------------------------------------------------------------------------
def sammle(daten):
    """Alles, was übersetzt werden müsste.
    Rückgabe: (woerter, texte) – woerter ist {bosnisch: deutsch},
    texte ist eine Menge deutscher Texte."""
    woerter, texte = {}, set()
    for s in daten.get("sektionen", []):
        texte.update(x for x in (s.get("label"), s.get("beschreibung")) if x)
    for k in daten.get("kategorien", []):
        texte.update(x for x in (k.get("label"), k.get("tipp")) if x)
        for w in k.get("words", []):
            woerter[w.get("bs", "")] = w.get("de", "")
    texte.update(s.get("de", "") for s in daten.get("saetze", []) if s.get("de"))
    for lektion in daten.get("grammatik", {}).values():
        for teil in lektion.get("erklaerung", []):
            if isinstance(teil, dict) and "tabelle" in teil:
                texte.update(z for reihe in teil["tabelle"] for z in reihe if z)
            elif teil:
                texte.add(teil)
        for u in lektion.get("uebungen", []):
            texte.update(x for x in (u.get("frage"), u.get("tipp")) if x)
            texte.update(o for o in u.get("optionen", []) if o)
    for g in daten.get("geschichten", []):
        texte.update(x for x in (g.get("stufe"), g.get("uebersetzung")) if x)
        texte.update(v for v in (g.get("vokabeln") or {}).values() if v)
        for f in g.get("fragen", []):
            if f.get("frage"):
                texte.add(f["frage"])
            texte.update(o for o in f.get("optionen", []) if o)
    texte.update(v for v in daten.get("woerterbuch", {}).values() if v)
    woerter.pop("", None)
    texte.discard("")
    texte -= GLEICH          # bosnische Beispiele brauchen keine Übersetzung
    return woerter, texte


def fehlende(daten, code):
    """{'woerter': [...], 'texte': [...]} – was in dieser Sprache noch fehlt."""
    if code == GRUNDSPRACHE:
        return {"woerter": [], "texte": []}
    hab_w = INHALT.get(code, {}).get("woerter", {})
    hab_t = INHALT.get(code, {}).get("texte", {})
    woerter, texte = sammle(daten)
    fehlt_w = sorted(bs for bs, de in woerter.items() if not hab_w.get(bs) and not hab_t.get(de))
    fehlt_t = sorted(x for x in texte if not hab_t.get(x))
    return {"woerter": fehlt_w, "texte": fehlt_t}


def stand(daten, code):
    """(fertig, gesamt) für die Anzeige in den Einstellungen."""
    woerter, texte = sammle(daten)
    gesamt = len(woerter) + len(texte)
    if code == GRUNDSPRACHE:
        return gesamt, gesamt
    f = fehlende(daten, code)
    return gesamt - len(f["woerter"]) - len(f["texte"]), gesamt
